B: Some Sums

 N 以下の整数の各桁の和を求め、適切に場合分けをして足し合わせてやればよいです。

#include <stdio . h>

 int main ()

{

          int n ,  a , b ;

         scanf (”%d%d%d” , &n , &a , &b ) ;

          int  r = 0;

           fo r  ( int   i = 1;   i <= n ;  i++)

          {

                    int  c = 0 ,  t =  i ;

                     fo r  ( int   j = 0;   j < 5;  j++)c +=  t % 10 ,  t /= 10;

                                    i f  ( a <= c&&c <= b) r +=  i ;

          }

         p r i n t f (”%d\n” ,  r ) ;

}
